import sys, types, importlib.abc, importlib.util, base64, zlib, html
from pathlib import Path as _Path

_BUNDLED = {'config.apikey': '', 'config.settings': '', 'utils.token_manager': '', 'scanner.kis_ws': '', 'scanner.board': '', 'scanner.prediction_memory': '', 'scanner.kis_engine': ''}

class _BundledLoader(importlib.abc.MetaPathFinder, importlib.abc.Loader):
    def find_spec(self, fullname, path=None, target=None):
        if fullname in _BUNDLED:
            return importlib.util.spec_from_loader(fullname, self, is_package=False)
        if fullname in ("scanner","utils","config","engine","data","ui"):
            return importlib.util.spec_from_loader(fullname, self, is_package=True)
        return None
    def create_module(self, spec):
        return None
    def exec_module(self, module):
        name = module.__name__
        if name in ("scanner","utils","config","engine","data","ui"):
            module.__path__ = []
            module.__package__ = name
            module.__file__ = str(_Path.cwd()/name/"__init__.py")
            return
        code = zlib.decompress(base64.b64decode(_BUNDLED[name])).decode("utf-8")
        module.__file__ = str(_Path.cwd().joinpath(*name.split(".")).with_suffix(".py"))
        module.__package__ = name.rpartition(".")[0]
        exec(compile(code, module.__file__, "exec"), module.__dict__)

sys.meta_path.insert(0, _BundledLoader())


