@st.cache_data(ttl=21600, show_spinner=False)
def kr_stock_master():
    rows = []
    if fdr is not None:
        try:
            df = fdr.StockListing("KRX")
            code_col = "Code" if "Code" in df.columns else "Symbol"
            name_col = "Name"
            market_col = "Market" if "Market" in df.columns else None
            for _, r in df.iterrows():
                code = str(r.get(code_col, "")).zfill(6)
                name = str(r.get(name_col, "")).strip()
                market_name = str(r.get(market_col, "KR")) if market_col else "KR"
                if code and name and code.isdigit():
                    rows.append((code, name, market_name))
        except Exception:
            rows = []
    if not rows:
        try:
            from pykrx import stock as krx_stock
            for market_name in ("KOSPI", "KOSDAQ", "KONEX"):
                for code in krx_stock.get_market_ticker_list(market=market_name):
                    name = krx_stock.get_market_ticker_name(code)
                    if code and name:
                        rows.append((str(code).zfill(6), str(name).strip(), market_name))
        except Exception:
            rows = []
    if not rows:
        rows = list(KR_CORE)
    return rows

def search_kr_names(query: str):
    q = (query or "").strip().lower()
    if not q:
        return []
    matches = []
    for code, name, market_name in kr_stock_master():
        if q in str(name).lower() or q in str(code):
            matches.append((code, name, market_name))
        if len(matches) >= 30:
            break
    return matches

